int Window::Run(){MSG msg{};while(GetMessageW(&msg,nullptr,0,0)>0){if(msg.message==WM_KEYDOWN){if(msg.wParam==VK_F7){Action(CompileFile);continue;}if(msg.wParam==VK_F5){Action((GetKeyState(VK_SHIFT)&0x8000)?StopFile:RunFile);continue;}if(GetKeyState(VK_CONTROL)&0x8000){if(msg.wParam=='S'){Action(SaveFile);continue;}if(msg.wParam=='O'){Action(Import);continue;}if(msg.wParam=='N'){Action(New);continue;}}}TranslateMessage(&msg);DispatchMessageW(&msg);}return static_cast<int>(msg.wParam);}
